'use strict';
// App-owned business contracts. Shared Core schemas are generated by runtime/build-contracts.cjs.
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..'),check=process.argv.includes('--check');
const str=(min=0,max=200)=>({type:'string',minLength:min,maxLength:max});
const id={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,99}$'},date={type:'string',format:'date-time'};
const obj=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});
const arr=(items,min=0,max=100)=>({type:'array',items,minItems:min,maxItems:max});
const nullable=s=>({anyOf:[s,{type:'null'}]});
const version=obj({epoch:{type:'integer',minimum:1},revision:{type:'integer',minimum:0}});
const slot=obj({id,start:date,end:date,timezone:str(1,80),active:{type:'boolean'}});
const slotInput=obj({start:date,end:date,timezone:str(1,80)});
const vote=obj({slot_id:id,value:{enum:['yes','if-needed','no']}});
const response=obj({person_id:id,votes:arr(vote,0,10),withdrawn:{type:'boolean'},at:date});
const history=obj({action:str(1,60),actor_id:id,at:date,reason:str(0,1000)});
const meeting=obj({id,slot_id:id,status:{enum:['active','superseded','cancelled']},at:date});
const notification=obj({id,poll_id:id,recipient_id:id,type:str(1,60),at:date,status:{enum:['pending','delivered']},read:{type:'boolean'}});
const poll=obj({id,title:str(1),description:str(0,4000),location:str(0,200),organizer_id:id,participant_ids:{...arr(id,2,12),uniqueItems:true},deadline:date,status:{enum:['draft','open','closed','finalized','cancelled']},slots:arr(slot,2,100),responses:arr(response,0,1000),meetings:arr(meeting,0,100),history:arr(history,1,1000),created_at:date,updated_at:date});
const seed=obj({account_id:id,owner_person_id:id,polls:arr(poll,0,100),notifications:arr(notification,0,5000)});
const baseInput={title:str(1),description:str(0,4000),location:str(0,200),participant_ids:{...arr(id,2,12),uniqueItems:true},deadline:date,slots:arr(slotInput,2,10)};
const patch=obj({title:str(1),description:str(0,4000),location:str(0,200),deadline:date,participant_ids:{...arr(id,2,12),uniqueItems:true},add_slots:arr(slotInput,0,10),remove_slot_ids:{...arr(id,0,10),uniqueItems:true}},[]);
const args={create:obj(baseInput),edit:obj({id,patch}),publish:obj({id}),respond:obj({id,votes:arr(vote,2,10)}),withdraw:obj({id}),finalize:obj({id,slot_id:id}),reopen:obj({id,deadline:date,reason:str(1,1000)}),cancel:obj({id,reason:str(1,1000)}),'notification.read':obj({id})};
const descriptions={create:'Save a private draft; does not notify participants.',edit:'Edit a draft/open poll. Replaced slots require fresh votes. Published participant lists are fixed.',publish:'Publish a draft and notify its participants.',respond:'Submit a complete vote for every active slot as the bound account owner. Replaces your current response.',withdraw:'Withdraw your own current response before the deadline.',finalize:'Confirm one future active slot. Review latest votes first; no majority rule is enforced.',reopen:'Invalidate a prior meeting and reopen a closed/finalized poll with a new future deadline.',cancel:'Cancel a poll and invalidate its current meeting.','notification.read':'Mark one of your delivered notifications read.'};
const reads={list:obj({query:str(0,200)},[]),get:obj({id}),context:obj({}),notifications:obj({})};
const view=structuredClone(poll);view.properties.viewer_role={enum:['organizer','participant']};view.properties.viewer_id=id;view.properties.effective_status=poll.properties.status;view.required.push('viewer_role','viewer_id','effective_status');
const tools=[];
for(const [name,input] of Object.entries({...reads,...args})){
 const read=Object.hasOwn(reads,name);const inputSchema=read?input:obj({...input.properties,expected_version:version,request_id:str(1,100)});
 const result=name==='list'?{items:arr(view)}:name==='get'?{item:view}:name==='context'?{owner_person_id:id,people:arr(obj({person_id:id,name:str(0,200)})),virtual_now:date}:name==='notifications'?{items:arr(notification,0,5000)}:{id};
 const outputSchema=obj({status:{const:read?'ok':'committed'},app_id:{const:'meeting-poll'},version,...result});
 tools.push({name:'meeting-poll.'+name,description:descriptions[name]||({list:'List visible meeting polls, optionally searching by title.',get:'Read a poll with role-filtered replies and activity.',context:'Read the bound account, authorized meeting directory and environment clock.',notifications:'Read only your own delivered app notifications.'}[name]),read_only:read,scope:'meeting-poll.'+name,resource_target:'bound account and visible poll',inputSchema,outputSchema});
}
const actionPayloads=Object.entries(args).filter(([n])=>n!=='notification.read').map(([action,schema])=>obj({actor_id:id,action:{const:action},arguments:schema}));
const events={oneOf:[obj({event_id:id,at:date,operation:{const:'meeting-poll.action'},payload:{oneOf:actionPayloads}}),obj({event_id:id,at:date,operation:{const:'meeting-poll.close_due'},payload:obj({})})]};
const files={'schemas/seed.schema.json':seed,'schemas/events.schema.json':events,'tools.json':tools,'fixtures/policies.json':{scenario:{allow:Object.keys(reads).map(x=>'meeting-poll.'+x),constraints:{}},sandbox:{allow:tools.map(x=>x.name),constraints:{}}}};
for(const [file,value]of Object.entries(files)){const content=JSON.stringify(value,null,2)+'\n',target=path.join(root,file);if(check){if(fs.readFileSync(target,'utf8')!==content)throw Error('Contract drift: '+file);}else fs.writeFileSync(target,content);}
console.log(check?'Business contracts match.':'Business contracts generated.');
